#!/usr/bin/env python3
"""Generates core/dict/vnpop_deinflect_rules.h from tools/yomitan_transforms.json.

The JSON is Yomitan's Japanese transform table (ext/js/language/ja/japanese-transforms.js) as
hoshidicts builds it (commit e6af33e), exported by vnreader's tools/dict_parity/run.sh transforms.
Rules, group names and condition bits are kept exactly, so vnpop_deinflect() gives the same
deinflections as Yomitan / Hoshi Reader. GPL-3.0, like Yomitan and hoshidicts.

Rules are sorted by their suffix (byte order) for a binary search; rules with the same suffix
keep their Yomitan order, which decides which of two equal results is found first.
"""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "yomitan_transforms.json")
OUT = os.path.join(HERE, "..", "core", "dict", "vnpop_deinflect_rules.h")


def c_str(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def main():
    data = json.load(open(SRC, encoding="utf-8"))
    groups = data["groups"]
    rules = data["rules"]
    order = sorted(range(len(rules)), key=lambda i: rules[i][0].encode("utf-8"))  # stable
    lines = [
        "/* Generated by tools/gen_deinflect_rules.py from tools/yomitan_transforms.json. Do not edit by hand.",
        " * Yomitan's Japanese transforms (GPL-3.0), as hoshidicts e6af33e builds them. */",
        "#ifndef VNPOP_DEINFLECT_RULES_H",
        "#define VNPOP_DEINFLECT_RULES_H",
        "",
        "#define VNPOP_DEINFLECT_MAX_SUFFIX_CHARS %d" % data["max_length"],
        "",
        "/* Group names, as Yomitan shows them in the inflection trace. */",
        "static const char *const s_rule_names[] = {",
    ]
    for g in groups:
        lines.append("    %s," % c_str(g["name"]))
    lines += ["};", "", "/* { suffix, replacement, suffix bytes, replacement bytes, conditions in, conditions out, group } */",
              "static const DeinflectRule s_rules[] = {"]
    for i in order:
        src, dst, cin, cout, gid = rules[i]
        lines.append("    {%s, %s, %d, %d, 0x%xu, 0x%xu, %d}," % (
            c_str(src), c_str(dst), len(src.encode()), len(dst.encode()), cin, cout, gid))
    lines += ["};", "", "#endif", ""]
    with open(OUT, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(lines))
    print("wrote %d rules, %d groups -> %s" % (len(rules), len(groups), os.path.relpath(OUT)))


if __name__ == "__main__":
    sys.exit(main())
